import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find strongly associated features (p < 0.01)
    strong_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'derived':
            t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
            if abs(p_val) < 0.01:
                strong_features.append((fid, t_stat))

    # Sort by effect size
    strong_features.sort(key=lambda x: abs(x[1]), reverse=True)

    # Remove near-duplicates (correlated with |r| >= 0.6)
    keep_features = set()
    correlations = {(f1,f2): r for f1,f2,r in [
        ('FCC10','WRP16P',1.00), ('VRL13','HFP10',0.94), ('VRL13','CJJS16',0.93),
        ('CQTU7','MCUF16B',0.93), ('EFIR19','YSMW19L',0.92), ('VRL13','CQA1P',-0.91),
        ('HFP10','YSMW19L',0.88), ('CJJS16','CQA1P',-0.88), ('DJW19','TOM12',0.87),
        ('VRL13','BIA13A',-0.87), ('CJJS16','HFP10',0.87), ('UIAW6','IHD10',0.85),
        ('VRL13','TOM12',0.85), ('VRL13','STHB17',0.85), ('VRL13','YSMW19L',0.84),
        ('HFP10','BIA13A',-0.84), ('TCHS4P','YSMW19L',0.83), ('HFP10','TCHS4P',0.83),
        ('VRL13','TCHS4P',0.83), ('BIA13A','YSMW19L',-0.83)
    ]}

    for fid, _ in strong_features:
        if any(fid in pair and any(f in keep_features for f in pair) 
               for pair in correlations if pair[0] != pair[1]):
            continue
        keep_features.add(fid)

    # If no strong features, return empty design
    if not keep_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Check for interaction terms among top features
    top_features = [fid for fid in strong_features if fid[0] in keep_features][:5]

    # Look for correlated pairs that might suggest interaction
    candidates = []
    for i, (f1, _) in enumerate(top_features):
        for j, (f2, _) in enumerate(top_features[i+1:], i+1):
            if (f1, f2) in correlations or (f2, f1) in correlations:
                candidates.append((f1, f2))

    # Try to find best interaction term
    if candidates:
        # For simplicity, use the first pair
        a, b = candidates[0]
        return Design(
            drivers=(a, b),
            columns=(a, b),
            products=((a, b),),
            loadings={a: 1.0, b: 1.0}
        )

    # If no interactions, return top single feature
    if top_features:
        fid = top_features[0][0]
        return Design(
            drivers=(fid,),
            columns=(fid,),
            products=(),
            loadings={fid: 1.0}
        )

    return Design(drivers=(), columns=(), products=(), loadings={})

